records=[]
for q in qs:
    r=D[q['id']]
    prefix=q['id']+':'
    a=r['independent_answer']
    if isinstance(a,str): a=prefix+a
    elif isinstance(a,list): a=[prefix+x for x in a]
    elif isinstance(a,dict): a={prefix+k:prefix+v if v else None for k,v in a.items()}
    ids=[c['id'] for c in q.get('choices',[])]
    if q['type']=='ordering': ids=[c['id'] for c in q['interaction']['steps']]
    if q['type']=='matching': ids=[c['id'] for c in q['interaction']['prompts']]+[c['id'] for c in q['interaction']['responses']]
    assert len(ids)==len(r['reasons']), (q['id'],ids,r['reasons'])
    # Keywords must be exact original source phrases, not translations or inferred labels.
    stem=' '.join(b.get('text','') for b in q['stem'])
    assert len(r['keywords'])<=3
    assert all(k in stem for k in r['keywords']), (q['id'],r['keywords'])
    r.update(id=q['id'],question_type=q['type'],independent_answer=a,concluded_at_utc=now,
        confidence='high' if r['status']=='verified' else 'medium',
        per_option=[{'id':oid,'verdict_reason_vi':why,'source_ids':r['source_ids']} for oid,why in zip(ids,r.pop('reasons'))],
        citations=[S[x] for x in r['source_ids']])
    if r['candidates'] is not None: r['candidates']=[prefix+x for x in r['candidates']]
    records.append(r)
out={'scope':'Q001-Q036','method':'Independent solve from blind questions, all source images, and primary AWS documentation; keys/reviews not read before this persistence.',
    'blinded':True,'answer_key_exposure_before_persistence':False,'persisted_at_utc':now,
    'primary_sources_opened_before_persistence':list(S.values()),'questions':records}
(ROOT/'independent.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'count':len(records),'option_units':sum(len(r['per_option']) for r in records),'timestamp':now,'statuses':{s:sum(r['status']==s for r in records) for s in ['verified','ambiguous','unresolved']}},ensure_ascii=False))
